// qiling/unpack/api_db.hpp — export name -> owning DLL.
//
// The table (api_db.inc) is generated by tools/gen_api_db.py from the host's
// mingw-w64 import libraries: an SDK export database, not corpus ground truth.
// See PLAN_UNPACK §0.17ae: recovering a payload's imports from a dump yields
// NAMES whose DLL is gone, and this is the only attribution source available on
// a Linux host (the reference reads real System32 DLLs, which are Windows-only,
// and taote's own rootfs stub DLLs are synthesized from the sample's packed
// imports, so they are circular for this purpose).
#ifndef QILING_UNPACK_API_DB_HPP
#define QILING_UNPACK_API_DB_HPP

#include <string>
#include <vector>

namespace qiling {
namespace unpack {

// The DLL stem that exports `name` (lowercase, no ".dll"), or nullptr when the
// name is not a known system export. Case-insensitive.
const char* api_owner(const std::string& name);

// Every DLL the table lists for `name`, in priority order (the first element is
// what api_owner returns). Empty when the name is unknown.
std::vector<std::string> api_owners(const std::string& name);

}  // namespace unpack
}  // namespace qiling

#endif  // QILING_UNPACK_API_DB_HPP
